func (q *Queries) ReleaseDeFiSource(ctx context.Context, delaySeconds int32, iD string, leaseToken *string) (int64, error) {
	result, err := q.db.Exec(ctx, releaseDeFiSource, delaySeconds, iD, leaseToken)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected(), nil
}
